scriptExample:
```powershell
# Get-StorageSpacesHealth.ps1 -- read-only standalone Storage Spaces snapshot
$ErrorActionPreference = 'Stop'
$schemaVersion = 1
$sampleEpoch = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
$snapshotId = [guid]::NewGuid().ToString()
$meta = @{ SplunkIndex='windows'; SplunkSource='powershell:storage-spaces-health'; SplunkSourceType='windows:storage_spaces:health'; SplunkHost=$env:COMPUTERNAME; SplunkTime=$sampleEpoch }
function Join-State($value) { (@($value | ForEach-Object { [string]$_ }) -join '|') }
function Emit($body) { [pscustomobject][ordered]($meta + $body) }
try {
  $pools = @(Get-StoragePool -IsPrimordial $false -ErrorAction Stop)
  $virtualByPool = @{}; $physicalByPool = @{}; $vCount = 0; $pCount = 0
  foreach ($pool in $pools) {
    $v = @(Get-VirtualDisk -StoragePool $pool -ErrorAction Stop)
    $p = @(Get-PhysicalDisk -StoragePool $pool -ErrorAction Stop)
    $virtualByPool[[string]$pool.UniqueId] = $v; $physicalByPool[[string]$pool.UniqueId] = $p
    $vCount += $v.Count; $pCount += $p.Count
  }
  Emit @{ schema_version=$schemaVersion; snapshot_id=$snapshotId; sample_epoch=$sampleEpoch; record_type='manifest'; collector_status='ok'; pool_count=$pools.Count; virtual_disk_count=$vCount; physical_disk_count=$pCount }
  foreach ($pool in $pools) {
    $poolId = [string]$pool.UniqueId
    Emit @{ schema_version=$schemaVersion; snapshot_id=$snapshotId; sample_epoch=$sampleEpoch; record_type='entity'; collector_status='ok'; object_type='pool'; object_id=$poolId; friendly_name=[string]$pool.FriendlyName; parent_pool_id='none'; health_status=[string]$pool.HealthStatus; operational_status=(Join-State $pool.OperationalStatus); is_read_only=[string]$pool.IsReadOnly; read_only_reason=[string]$pool.ReadOnlyReason; size_bytes=[uint64]$pool.Size; allocated_bytes=[uint64]$pool.AllocatedSize }
    foreach ($vd in $virtualByPool[$poolId]) {
      Emit @{ schema_version=$schemaVersion; snapshot_id=$snapshotId; sample_epoch=$sampleEpoch; record_type='entity'; collector_status='ok'; object_type='virtual_disk'; object_id=[string]$vd.UniqueId; friendly_name=[string]$vd.FriendlyName; parent_pool_id=$poolId; health_status=[string]$vd.HealthStatus; operational_status=(Join-State $vd.OperationalStatus); is_read_only='false'; detached_reason=[string]$vd.DetachedReason; resiliency_setting=[string]$vd.ResiliencySettingName; size_bytes=[uint64]$vd.Size; allocated_bytes=[uint64]$vd.AllocatedSize }
    }
    foreach ($pd in $physicalByPool[$poolId]) {
      Emit @{ schema_version=$schemaVersion; snapshot_id=$snapshotId; sample_epoch=$sampleEpoch; record_type='entity'; collector_status='ok'; object_type='physical_disk'; object_id=[string]$pd.UniqueId; friendly_name=[string]$pd.FriendlyName; parent_pool_id=$poolId; health_status=[string]$pd.HealthStatus; operational_status=(Join-State $pd.OperationalStatus); is_read_only='false'; usage=[string]$pd.Usage; physical_location=[string]$pd.PhysicalLocation; model=[string]$pd.Model; firmware_version=[string]$pd.FirmwareVersion; size_bytes=[uint64]$pd.Size; allocated_bytes=[uint64]$pd.AllocatedSize }
    }
  }
} catch {
  Emit @{ schema_version=$schemaVersion; snapshot_id=$snapshotId; sample_epoch=$sampleEpoch; record_type='collector_error'; collector_status='error'; error_type=$_.Exception.GetType().FullName; error_message=$_.Exception.Message }
  exit 1
}
